	 (1,'icms_saida','{"view_nome": "mxf_vw_icms", "view_sql": "SELECT distinct\ncodigo_produto, \nean, \ntipo_mva, \nmva, \nmva_distribuidor, \nre_29560, \ncase when cest = ''00.000.00'' then null else cest end as cest, \nsac_cst, \nsac_alq, \nsac_alqst, \ncase when sac_cst= ''41'' and sac_rbc= ''100.000'' then 0.000 when sac_cst = ''40'' and sac_rbc = ''100.000'' then 0.000 else sac_rbc end as sac_rbc, \nsac_rbcst, \nsas_cst, \nsas_alq, \nsas_alqst, \ncase when sas_cst= ''41'' and sas_rbc= ''100.000'' then 0.000 when sas_rbc = ''40'' and sas_rbc = ''100.000'' then 0.000 else sas_rbc end as sas_rbc, \nsas_rbcst, \nsvc_cst, \nsvc_alq, \nsvc_alqst, \ncase when svc_cst= ''41'' and svc_rbc= ''100.000'' then 0.000 when svc_rbc = ''40'' and svc_rbc = ''100.000'' then 0.000 else svc_rbc end as svc_rbc, \nsvc_rbcst, \nsnc_cst, \nsnc_alq, \nsnc_alqst, \ncase when snc_cst = ''41'' and snc_rbc = ''100.000'' then 0.000 when snc_cst = ''40'' and snc_rbc = ''100.000'' then 0.000 else snc_rbc end as snc_rbc,\nsnc_rbcst,\ncase when fecp is null then 0 else fecp end as fecp,\nstatus\n\n\nFROM mxf_vw_icms\nWHERE STATUS = ''ATIVO''", "tmp_nome": "mxf_tmp_icms_saida_{estado}", "tmp_delete": "delete from mxf_tmp_icms_saida_{estado}", "flag1": true, "flag2": false, "flag3": false, "tmp_insert": "INSERT INTO mxf_tmp_icms_saida_{estado} (\n    codigo_produto,\n    ean,\n    sac_cst,\n    sac_alq,\n    sac_alqst,\n    sac_rbc,\n    sac_rbcst,\n    sas_cst,\n    sas_alq,\n    sas_alqst,\n    sas_rbc,\n    sas_rbcst,\n    svc_cst,\n    svc_alq,\n    svc_alqst,\n    svc_rbc,\n    svc_rbcst,\n    snc_cst,\n    snc_alq,\n    snc_alqst,\n    snc_rbc,\n    cest,\n    FECP,\n    fundamento_legal\n)", "tmp_values": "%%CODIGO_PRODUTO%%,\n    %%EAN%%,\n    %%SAC_CST%%,\n    %%SAC_ALQ%%,\n    %%SAC_ALQ_ST%%,\n    %%SAC_RBC%%,\n    %%SAC_RBC_ST%%,\n    %%SAS_CST%%,\n    %%SAS_ALQ%%,\n    %%SAS_ALQ_ST%%,\n    %%SAS_RBC%%,\n    %%SAS_RBC_ST%%,\n    %%SVC_CST%%,\n    %%SVC_ALQ%%,\n    %%SVC_ALQ_ST%%,\n    %%